    category_totals = {}
    for entry in entries:
        # Check if this entry is from the requested month
        key = f"{entry.day.year}-{entry.day.month}"
        if key == month:
            category = entry.category
            amount = entry.amount

            # Accumulate the amount
            if category not in category_totals:
                category_totals[category] = amount
            else:
                category_totals[category] += amount

    # Filter out categories with zero total and create list of tuples
    result = []
    for category, total in category_totals.items():
        if total != 0:  # Skip zero totals
            result.append((category, total))

    # Sort by total ascending (most negative/expensive first), then by category name
    result.sort(key=lambda x: (x[1], x[0]))

